import { existsSync } from 'node:fs'
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises'
import { dirname } from 'node:path'
import process from 'node:process'
import { virtualModuleId } from './constant'

/** First line of a file this plugin owns; anything else is left alone. */
const GENERATED_HEADER = '// Generated by vite-plugin-uni-layouts'

/**
 * Declaration for the runtime part of `virtual:uni-layouts` and for the layout
 * names found in the project.
 *
 * The helper is generated by the plugin, so its types have nowhere else to
 * live. Writing them into the project keeps the import typed without asking the
 * user to reference the package's `/client` entry. `ShallowRef` is imported
 * inline so the file needs no lint directives.
 *
 * Only exports that the virtual module really has may be declared here: an
 * extra one silently overrides the same name from `client.d.ts`, because two
 * `declare module` blocks merge without a duplicate-name error.
 *
 * `UniHelperUniLayouts` is the hook `@uni-helper/uni-pages-types` reads to type
 * the `layout` field of a page. It stays a plain global interface on purpose:
 * this file has to remain a script to declare `virtual:uni-layouts` (a module
 * file cannot declare a module it cannot resolve), and a `declare module` for a
 * real package in a script shadows that package instead of augmenting it.
 */
export function getDeclaration(layoutNames: string[]): string {
  // several files can derive the same name (`a.vue` and `a/index.vue`), and a
  // duplicate interface member does not compile
  const names = Array.from(new Set(layoutNames)).sort()
  const members = names.map(name => `  ${getMemberKey(name)}: true`).join('\n')

  return `${GENERATED_HEADER}

interface UniHelperUniLayouts {
${members}
}

declare module '${virtualModuleId}' {
  export type LayoutKey = keyof UniHelperUniLayouts extends never ? string : keyof UniHelperUniLayouts
  export function useUhUniLayoutRef<T = Record<string, any>>(): import('vue').ShallowRef<T | null>
}
`
}

/**
 * Property key for a layout name. A plain name stays unquoted so the committed
 * playground declaration passes lint; anything else (a name that starts with a
 * digit, holds non-ASCII characters or a quote) is escaped and quoted so the
 * declaration still parses.
 */
function getMemberKey(name: string): string {
  if (/^[a-z_$][\w$]*$/i.test(name))
    return name
  return JSON.stringify(name)
}

/**
 * Write the declaration file, creating the directory and skipping an unchanged
 * file. A file at the same path without the generated header belongs to the
 * user and is never replaced.
 */
export async function writeDeclaration(filePath: string, layoutNames: string[]): Promise<void> {
  const code = getDeclaration(layoutNames)

  if (existsSync(filePath)) {
    const current = await readFile(filePath, 'utf-8')
    if (current === code)
      return
    if (!current.startsWith(GENERATED_HEADER)) {
      console.warn(`[vite-plugin-uni-layouts] ${filePath} was not generated by this plugin, leaving it alone`)
      return
    }
  }

  await mkdir(dirname(filePath), { recursive: true })
  // write next to the target and rename, so a reader (tsc, the editor) never
  // sees a half-written file; the pid keeps a dev server and a build that run
  // at the same time from sharing a temporary name
  const tmpPath = `${filePath}.${process.pid}.tmp`
  await writeFile(tmpPath, code, 'utf-8')
  await rename(tmpPath, filePath)
}
